const { mkdir, cp, copyFile } = require('node:fs/promises');
const path = require('node:path');

async function main() {
  const target = path.resolve('.web-build');
  await mkdir(target, { recursive: true });
  await cp('dist/packages/web/src', path.join(target, 'src'), { recursive: true });
  await copyFile('packages/web/index.html', path.join(target, 'index.html'));
  // Runtime config is generated by CDK. This artifact alone cannot enable demo mode.
}
main().catch(error => { console.error(error); process.exitCode = 1; });
